def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg]
    # Matching diagonal marks define a line; extend both ends until an
    # existing non-background cell or the boundary blocks the ray.
    for i,(r,c,v) in enumerate(pts):
        for rr,cc,vv in pts[i+1:]:
            if vv!=v or rr==r or abs(rr-r)!=abs(cc-c):
                continue
            dr=1 if rr>r else -1
            dc=1 if cc>c else -1
            for y,x,sy,sx in ((r-dr,c-dc,-dr,-dc),(rr+dr,cc+dc,dr,dc)):
                while 0<=y<h and 0<=x<w and out[y][x]==bg:
                    out[y][x]=v
                    y+=sy
                    x+=sx
    return out
